import clsx from 'clsx';
import React, { ReactNode, useEffect, useState } from 'react';
import ReactDOM from 'react-dom';
import { getAppRoot } from '@/utils/appQuery';

interface ModalPortalProps {
  children: ReactNode;
  showOverlay?: boolean;
}

// Coordinated overlay z-index scale (all clear the desktop `.window-border`
// page frame at z-99 — see globals.css). Low -> high:
//   100 RSVP overlay · 101 RSVP controls · 110 Settings dialog ·
//   120 modal / command palette · 130 toast · 200 app-lock.
// ModalPortal is the top modal layer, so it sits above the Settings dialog —
// a modal opened from inside Settings (e.g. Add OPDS Catalog) must win.
// Invariants are enforced by src/__tests__/styles/zIndexScale.test.ts.
const ModalPortal: React.FC<ModalPortalProps> = ({ children, showOverlay = true }) => {
  // 独立运行时挂 document.body；embed 运行时必须挂到 shadow root 内部，
  // 否则弹层会跑到宿主页面上、且拿不到 embed 的样式（Tailwind 作用域在 shadow 内）。
  // 注意：embed 下 getAppRoot() 返回的是 shadow 内的容器**元素**（styleHost），
  // 不是 ShadowRoot 实例 —— 旧写法 `getAppRoot() instanceof ShadowRoot` 永远为
  // false，所有走 ModalPortal 的弹窗（分组/标签/删除确认…）都被挂到宿主 body
  // 上，样式全丢、形同隐身（#reader-embed-modals-invisible）。
  //
  // SSR 安全：静态导出（output: export）在「Collecting page data」阶段会在 Node
  // 里预渲染组件，此时没有 document / ShadowRoot，直接访问会抛
  // `ReferenceError: document is not defined` 并中断整个导出。
  // 因此容器解析延迟到客户端挂载后再做 —— 挂载前不渲染 portal，
  // 弹层在这一帧内不存在（模态框本就是交互后才出现，无可见副作用）。
  const [container, setContainer] = useState<HTMLElement | ShadowRoot | null>(null);

  useEffect(() => {
    const root = getAppRoot();
    // `ShadowRoot` 在 Node（SSR / 预渲染）里根本不存在，
    // 直接写 `x instanceof ShadowRoot` 会抛 ReferenceError。
    // 用 typeof 守卫，两种运行环境都安全。
    const hasShadowRoot = typeof ShadowRoot !== 'undefined';
    const rootNode =
      hasShadowRoot && root instanceof ShadowRoot ? root : root?.getRootNode?.();
    setContainer(
      hasShadowRoot && rootNode instanceof ShadowRoot ? rootNode : document.body,
    );
  }, []);

  if (!container) return null;

  return ReactDOM.createPortal(
    <div
      data-capture-blocking-overlay='true'
      className={clsx(
        'fixed inset-0 isolate z-[120] flex items-center justify-center',
        showOverlay && 'bg-black/50',
      )}
      style={{ transform: 'translateZ(0)' }}
    >
      {children}
    </div>,
    container,
  );
};

export default ModalPortal;
